import React, { useState, useEffect } from 'react';

const DiscoverySettings = ({ currentUser }) => {
    const [settings, setSettings] = useState({
        maxDistance: 25,
        minAge: 18,
        maxAge: 40,
        showOnlineOnly: false,
        showPassportUsers: true,
        hideDistance: false,
        notifyNearby: true,
        notifyMatch: true,
        notifyMessage: true,
        shareLocation: true
    });
    const [saving, setSaving] = useState(false);

    useEffect(() => {
        if (!currentUser) return;
        const fetchSettings = async () => {
            try {
                const response = await fetch(`${process.env.REACT_APP_API_URL || `http://${window.location.hostname}:5000`}/api/user/${currentUser.phone}/settings/discovery`);
                if (response.ok) {
                    const result = await response.json();
                    if (result.data) {
                        setSettings({
                            maxDistance: result.data.max_distance || 25,
                            minAge: result.data.min_age || 18,
                            maxAge: result.data.max_age || 40,
                            showOnlineOnly: result.data.show_online_only || false,
                            showPassportUsers: result.data.show_passport_users ?? true,
                            hideDistance: result.data.hide_distance ?? false,
                            notifyNearby: result.data.notify_nearby ?? true,
                            notifyMatch: result.data.notify_match ?? true,
                            notifyMessage: result.data.notify_message ?? true,
                            shareLocation: result.data.share_location ?? true
                        });
                    }
                }
            } catch (err) {
                console.error("Failed to fetch discovery settings", err);
            }
        };
        fetchSettings();
    }, [currentUser]);

    const handleSave = async () => {
        setSaving(true);
        try {
            await fetch(`${process.env.REACT_APP_API_URL || `http://${window.location.hostname}:5000`}/api/user/${currentUser.phone}/settings/discovery`, {
                method: 'PUT',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    max_distance: settings.maxDistance,
                    min_age: settings.minAge,
                    max_age: settings.maxAge,
                    show_online_only: settings.showOnlineOnly,
                    show_passport_users: settings.showPassportUsers,
                    hide_distance: settings.hideDistance,
                    notify_nearby: settings.notifyNearby,
                    notify_match: settings.notifyMatch,
                    notify_message: settings.notifyMessage,
                    share_location: settings.shareLocation
                })
            });
            alert('Discovery settings saved successfully!');
        } catch (err) {
            console.error(err);
            alert('Failed to save settings');
        } finally {
            setSaving(false);
        }
    };

    return (
        <div style={{ padding: '30px', maxWidth: '800px', margin: '0 auto' }}>
            <h1 style={{ fontSize: '2rem', color: '#1f2937', marginBottom: '30px' }}>⚙️ Discovery Settings</h1>

            <div style={{ backgroundColor: 'white', padding: '30px', borderRadius: '12px', boxShadow: '0 4px 6px rgba(0,0,0,0.1)' }}>
                {/* Distance Slider */}
                <div style={{ marginBottom: '30px' }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '10px' }}>
                        <label style={{ fontWeight: 'bold', color: '#374151' }}>📏 Maximum Distance</label>
                        <span style={{ color: '#e11d48', fontWeight: 'bold' }}>{settings.maxDistance} km</span>
                    </div>
                    <input 
                        type="range" 
                        min="5" max="100" 
                        value={settings.maxDistance}
                        onChange={(e) => setSettings({...settings, maxDistance: e.target.value})}
                        style={{ width: '100%', cursor: 'pointer' }}
                    />
                </div>

                {/* Age Range */}
                <div style={{ marginBottom: '30px' }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '10px' }}>
                        <label style={{ fontWeight: 'bold', color: '#374151' }}>🗓️ Age Range</label>
                        <span style={{ color: '#e11d48', fontWeight: 'bold' }}>{settings.minAge} - {settings.maxAge}</span>
                    </div>
                    <div style={{ display: 'flex', gap: '20px', alignItems: 'center' }}>
                        <input 
                            type="range" min="18" max="100" 
                            value={settings.minAge}
                            onChange={(e) => setSettings({...settings, minAge: Math.min(e.target.value, settings.maxAge - 1)})}
                            style={{ flex: 1, cursor: 'pointer' }}
                        />
                        <input 
                            type="range" min="18" max="100" 
                            value={settings.maxAge}
                            onChange={(e) => setSettings({...settings, maxAge: Math.max(e.target.value, parseInt(settings.minAge) + 1)})}
                            style={{ flex: 1, cursor: 'pointer' }}
                        />
                    </div>
                </div>

                {/* Toggles */}
                <div style={{ display: 'flex', flexDirection: 'column', gap: '20px', marginBottom: '40px' }}>
                    <label style={{ display: 'flex', alignItems: 'center', cursor: 'pointer' }}>
                        <input 
                            type="checkbox" 
                            checked={settings.showOnlineOnly}
                            onChange={(e) => setSettings({...settings, showOnlineOnly: e.target.checked})}
                            style={{ width: '20px', height: '20px', marginRight: '15px' }}
                        />
                        <span style={{ fontSize: '1.1rem', color: '#374151' }}>🟢 Show Online Only</span>
                    </label>

                    <label style={{ display: 'flex', alignItems: 'center', cursor: 'pointer' }}>
                        <input 
                            type="checkbox" 
                            checked={settings.showPassportUsers}
                            onChange={(e) => setSettings({...settings, showPassportUsers: e.target.checked})}
                            style={{ width: '20px', height: '20px', marginRight: '15px' }}
                        />
                        <span style={{ fontSize: '1.1rem', color: '#374151' }}>🌍 Show Passport Users</span>
                    </label>

                    <label style={{ display: 'flex', alignItems: 'center', cursor: 'pointer' }}>
                        <input 
                            type="checkbox" 
                            checked={settings.hideDistance}
                            onChange={(e) => setSettings({...settings, hideDistance: e.target.checked})}
                            style={{ width: '20px', height: '20px', marginRight: '15px' }}
                        />
                        <span style={{ fontSize: '1.1rem', color: '#374151' }}>🔒 Hide My Distance</span>
                    </label>
                </div>

                <hr style={{ border: 'none', borderTop: '1px solid #e5e7eb', margin: '30px 0' }} />

                <h2 style={{ fontSize: '1.5rem', color: '#1f2937', marginBottom: '20px' }}>📱 Real-time Controls (RabbitMQ)</h2>
                <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(250px, 1fr))', gap: '20px', marginBottom: '40px' }}>
                    <div style={{ padding: '15px', backgroundColor: '#f9fafb', borderRadius: '12px', border: '1px solid #e5e7eb' }}>
                        <label style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', cursor: 'pointer' }}>
                            <span style={{ fontSize: '1.1rem', color: '#374151', fontWeight: 'bold' }}>🔔 Nearby Users</span>
                            <input 
                                type="checkbox" 
                                checked={settings.notifyNearby}
                                onChange={(e) => setSettings({...settings, notifyNearby: e.target.checked})}
                                style={{ width: '24px', height: '24px', accentColor: '#e11d48' }}
                            />
                        </label>
                        <p style={{ margin: '5px 0 0 0', fontSize: '0.85rem', color: '#6b7280' }}>Toggle when new users enter radius</p>
                    </div>

                    <div style={{ padding: '15px', backgroundColor: '#f9fafb', borderRadius: '12px', border: '1px solid #e5e7eb' }}>
                        <label style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', cursor: 'pointer' }}>
                            <span style={{ fontSize: '1.1rem', color: '#374151', fontWeight: 'bold' }}>💕 New Match</span>
                            <input 
                                type="checkbox" 
                                checked={settings.notifyMatch}
                                onChange={(e) => setSettings({...settings, notifyMatch: e.target.checked})}
                                style={{ width: '24px', height: '24px', accentColor: '#e11d48' }}
                            />
                        </label>
                        <p style={{ margin: '5px 0 0 0', fontSize: '0.85rem', color: '#6b7280' }}>Toggle match notifications</p>
                    </div>

                    <div style={{ padding: '15px', backgroundColor: '#f9fafb', borderRadius: '12px', border: '1px solid #e5e7eb' }}>
                        <label style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', cursor: 'pointer' }}>
                            <span style={{ fontSize: '1.1rem', color: '#374151', fontWeight: 'bold' }}>💬 New Message</span>
                            <input 
                                type="checkbox" 
                                checked={settings.notifyMessage}
                                onChange={(e) => setSettings({...settings, notifyMessage: e.target.checked})}
                                style={{ width: '24px', height: '24px', accentColor: '#e11d48' }}
                            />
                        </label>
                        <p style={{ margin: '5px 0 0 0', fontSize: '0.85rem', color: '#6b7280' }}>Toggle message notifications</p>
                    </div>

                    <div style={{ padding: '15px', backgroundColor: '#f9fafb', borderRadius: '12px', border: '1px solid #e5e7eb' }}>
                        <label style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', cursor: 'pointer' }}>
                            <span style={{ fontSize: '1.1rem', color: '#374151', fontWeight: 'bold' }}>📍 Location Updates</span>
                            <input 
                                type="checkbox" 
                                checked={settings.shareLocation}
                                onChange={(e) => setSettings({...settings, shareLocation: e.target.checked})}
                                style={{ width: '24px', height: '24px', accentColor: '#e11d48' }}
                            />
                        </label>
                        <p style={{ margin: '5px 0 0 0', fontSize: '0.85rem', color: '#6b7280' }}>Toggle real-time location sharing</p>
                    </div>
                </div>

                <button 
                    onClick={handleSave}
                    disabled={saving}
                    style={{
                        width: '100%',
                        padding: '15px',
                        backgroundColor: '#e11d48',
                        color: 'white',
                        border: 'none',
                        borderRadius: '8px',
                        fontSize: '1.1rem',
                        fontWeight: 'bold',
                        cursor: saving ? 'not-allowed' : 'pointer',
                        opacity: saving ? 0.7 : 1
                    }}
                >
                    {saving ? 'Saving...' : 'Save Settings'}
                </button>
            </div>
        </div>
    );
};

export default DiscoverySettings;
